INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP10-114', 'X-Drake', 'CHARACTER', 3, 3000, 2000, NULL, 'Tranchant', 'Supernovae/Marine/Équipage de Drake', '[Activation : Principale] Vous pouvez épuiser ce Personnage : Si le nombre de cartes de votre Vie est inférieur ou égal à celui de la Vie adverse, épuisez jusqu''à 1 Personnage adverse ayant un coût de 4 ou moins.', NULL, 'tasaka', 'Jaune', 'UC', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP10-116', 'Damned Punk', 'EVENT', 4, NULL, NULL, NULL, NULL, 'Supernovae/Équipage de Kidd', '[Principale] Regardez jusqu''à 1 carte du dessus de votre Vie ou de celle de votre adversaire et placez-la au-dessus ou au-dessous de la Vie. Puis, mettez KO jusqu''à 1 Personnage adverse ayant un coût de 5 ou moins.', 'Piochez 2 cartes et défaussez 1 carte de votre main.', NULL, 'Jaune', 'R', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP10-117', 'ROOM', 'EVENT', 1, NULL, NULL, NULL, NULL, 'Supernovae/Équipage du Heart', '[Contre] Si vous avez 1 carte ou moins dans votre Vie, jusqu''à 1 de vos Leaders ou Personnages gagne +3000 de puissance pour tout le combat. Puis, redressez jusqu''à 1 de vos Personnages ayant un coût de 5 ou moins.', 'Piochez 1 carte.', NULL, 'Jaune', 'UC', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
