INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP12-077', '"Grâce à cette technique, personne ne pourra entendre les sons que tu produiras."', 'EVENT', 2, NULL, NULL, NULL, NULL, 'Équipage du Heart', '[Principale] Choisissez jusqu''à 1 de vos [Trafalgar Law] ; il gagne +2000 de puissance pour tout le tour. Puis, si la carte choisie attaque durant ce tour, votre adversaire ne peut pas activer [Bloqueur].', 'Piochez 1 carte.', NULL, 'Violet', 'C', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
