INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP12-078', 'Brochette', 'EVENT', 3, NULL, NULL, NULL, NULL, 'Équipage de Chapeau de paille', '[Principale] Si le nombre de cartes DON!! sur votre terrain est inférieur ou égal à celui du terrain de votre adversaire, piochez 1 carte. Puis, jusqu''à 1 Personnage adverse perd -3000 de puissance pour tout le tour.', NULL, NULL, 'Violet', 'UC', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
