INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('OP12-080', 'Baratie', 'STAGE', 1, NULL, NULL, NULL, NULL, 'East Blue', '[Activation : Principale] Vous pouvez placer ce Lieu au-dessous du deck de son propriétaire : Si votre Leader est [Sanji], regardez 3 cartes du dessus de votre deck, révélez jusqu''à 1 Événement et ajoutez-le à votre main. Puis, placez les cartes restantes au-dessous de votre deck dans l''ordre de votre choix.', 'Jouez cette carte.', NULL, 'Violet', 'C', 3, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
