INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('EB04-001', 'Jewelry Bonney', 'LEADER', NULL, 5000, NULL, 4, 'Spécial', 'Egg Head/Équipage de Bonney', '[Tour adverse] Si vous avez 1 carte ou moins dans votre Vie, ce Leader gagne +2000 de puissance. [Activation : Principale] [Une fois par tour] Jusqu''à 1 Personnage adverse perd −1000 de puissance pour tout le tour. Puis, si vous avez 2 cartes ou plus dans votre Vie, vous pouvez ajouter à votre main 1 carte du dessus de votre Vie.', NULL, 'Sunohara', 'Rouge/Jaune', 'L', 4, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
