INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('EB04-042', 'Alpha', 'CHARACTER', 1, 2000, 2000, NULL, 'Frappe', 'CP8', '[Jouée] Vous pouvez placer dans votre Défausse 3 cartes du dessus de votre deck : Réduisez de −1 le coût de jusqu''à 1 Personnage adverse pour tout le tour.', NULL, 'Koushi Rokushiro', 'Noir', 'C', 4, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('EB04-040', 'Flame Dragon Torch', 'EVENT', 1, NULL, NULL, NULL, NULL, 'The Four Emperors/Animal Kingdom Pirates', '[Main] You may rest 6 of your DON!! cards: Up to 1 of your [Kaido] cards gains +3000 power during this turn. Then, rest up to 1 of your opponent''s Characters. [Counter] DON!! −1: Your Leader gains +4000 power during this battle.', NULL, NULL, 'Violet', 'R', 4, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
