INSERT INTO public.card_details (code, name, category, cost, power, counter, life, attribute, types, effect, trigger, illust, color, rarity, block, language) VALUES ('EB04-044', 'Kobby', 'CHARACTER', 6, 7000, 1000, NULL, 'Frappe', 'Marine/SWORD', '[Une fois par tour] Si votre Leader inclut «Marine» dans son type et que ce Personnage quitte le terrain, vous pouvez défausser 1 carte de votre main à la place. [Votre tour] [Une fois par tour] Quand un Personnage adverse est mis KO, piochez 1 carte.', NULL, 'Yuu Shimotsuki', 'Noir', 'SR', 4, 'fr') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, effect = EXCLUDED.effect, cost = EXCLUDED.cost, power = EXCLUDED.power, counter = EXCLUDED.counter, types = EXCLUDED.types, attribute = EXCLUDED.attribute;
